```python
import pyautogui
import time

def keylogger():
    while True:
        time.sleep(0.1)
        pressed_key = pyautogui.key_down()
        if pressed_key:
            print(f"Key press: {pressed_key}")

if __name__ == "__main__":
    keylogger()

